							cont = "$SecondSix";
							print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$SecondSix*FUNCTION*Omo*vis_con SET " + row + " \0");
							row = row + 1;
							
