									row_id = row_id + 1;
									print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side" + whichside + "$PartnershipBar$PartnershipBarOut$"
											+ "PartnershipBarAll$PartnershipBarDataAll$SelectRows$Row" + row_id  + "$RowAnim$SelectPart*FUNCTION*Omo*vis_con SET " + "1" + " \0");
