	public void populateHowoutquick(PrintWriter print_writer,String viz_scene,MatchAllData match, String broadcaster,int whichside) throws InterruptedException 
	{	
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: HowOutQuick's inning is null";
		} else {
			
			for(Inning inn : match.getMatch().getInning()) {
				if(inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					if(inn.getBattingTeamId() == match.getSetup().getHomeTeamId()) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side" + whichside + "$Single$img_TeamBadges*TEXTURE*IMAGE SET " 
								+ logo_path + match.getSetup().getHomeTeam().getTeamName4() + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side" + whichside + "$Single$img_TeamBadges*TEXTURE*IMAGE SET " 
								+ logo_path + match.getSetup().getAwayTeam().getTeamName4() + "\0");
					}
					
					for (BattingCard bc : inn.getBattingCard()) {
						if(inn.getFallsOfWickets().size() > 0) {
							if(inn.getFallsOfWickets().get(inn.getFallsOfWickets().size() - 1).getFowPlayerID() == bc.getPlayerId()) {
								
								String[] Count = CricketFunctions.getScoreTypeData(CricketUtil.BATSMAN,match, inn.getInningNumber(), bc.getPlayerId(),",", 
										match.getEventFile().getEvents()).split(",");
								
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$PlyerName$txt_FirstName*GEOM*TEXT SET " + bc.getPlayer().getFirstname() + " \0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$PlyerName$txt_lastName*GEOM*TEXT SET " + bc.getPlayer().getSurname() + "\0");
								
								if(bc.getHowOutPartOne().trim() == "") {
									print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + "" + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutText() + "\0");
								}else {
									if(bc.getHowOut().equalsIgnoreCase(CricketUtil.LBW)) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutPartTwo() + "\0");
									}else if(bc.getHowOut().equalsIgnoreCase(CricketUtil.RUN_OUT)) {
										if(bc.getWasHowOutFielderSubstitute() != null && bc.getWasHowOutFielderSubstitute().equalsIgnoreCase(CricketUtil.YES)) {
											if(CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(), inn.getInningNumber(),bc.getHowOutFielderId()).equalsIgnoreCase(CricketUtil.YES) || 
													CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(), inn.getInningNumber(), bc.getHowOutFielderId()).equalsIgnoreCase(CricketUtil.YES)) {
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET (" + bc.getHowOutPartTwo().split(" ")[0] + ") \0");
											}else {
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + " (sub - " + bc.getHowOutPartTwo().split(" ")[0] + ")" + " \0");
											}
										}else {
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutPartTwo() + "\0");
										}
									}else if(bc.getHowOut().equalsIgnoreCase(CricketUtil.CAUGHT)) {
										if(CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(), inn.getInningNumber(), bc.getHowOutFielderId()).equalsIgnoreCase(CricketUtil.YES) || 
												CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(), inn.getInningNumber(), bc.getHowOutFielderId()).equalsIgnoreCase(CricketUtil.YES)) {
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne().replace("(SUB)", "") + "\0");
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutPartTwo() + "\0");
										}else {
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
											print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutPartTwo() + "\0");
										}
									}else {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + bc.getHowOutPartOne() + "\0");
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$Batsman_Out$MiddleDataGrp$txt_BowlerName*GEOM*TEXT SET " + bc.getHowOutPartTwo() + "\0");
									}
								}
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$ScoreGrp$txt_Runs*GEOM*TEXT SET " + bc.getRuns() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$ScoreGrp$txt_Balls*GEOM*TEXT SET " + bc.getBalls() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$StatGrp$Grp1$txt_StatValue*GEOM*TEXT SET " + Count[0] + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$StatGrp$Grp2$txt_StatValue*GEOM*TEXT SET " + bc.getFours() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$StatGrp$Grp3$txt_StatValue*GEOM*TEXT SET " + bc.getSixes() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET " + bc.getStrikeRate() + "\0");
							}
						}						
					}
				}
			}
		}
	}
