	public void populateLTNextToBat(PrintWriter print_writer,String viz_scene,List<Statistics> stats,List<Player> plyr,MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			int row_id=0;
			double strike_rate = 0;
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1*FUNCTION*Omo*vis_con SET 15 \0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side1*FUNCTION*Omo*vis_con SET 0 \0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$BandGrp$Side1*FUNCTION*Omo*vis_con SET 3 \0");
		
			for(Inning inn : match.getMatch().getInning()) {
				if(inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side1$Single$img_TeamBadges*TEXTURE*IMAGE SET " + logo_path + 
							inn.getBatting_team().getTeamName4() + "\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$PlyerName$txt_FirstName*GEOM*TEXT SET " + 
							inn.getBatting_team().getTeamName1() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$PlyerName$txt_lastName*GEOM*TEXT SET " + 
							"" + "\0");
					
					for(int b=1;b<=inn.getBattingCard().size();b++) {
						if(inn.getBattingCard().get(b-1).getStatus().equalsIgnoreCase(CricketUtil.STILL_TO_BAT)) {
							row_id = row_id + 1;
							if(row_id <= 3) {
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$StatGrp$Grp" + row_id + "$txt_StatHead*GEOM*TEXT SET " + 
										"IN AT " + b + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$StatGrp$Grp" + row_id + "$txt_StatValue*GEOM*TEXT SET " + 
										inn.getBattingCard().get(b-1).getPlayer().getFull_name() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$StatGrp$Grp" + row_id + "$txt_StatValue2*GEOM*TEXT SET " + 
										"T20 STRIKE RATE : " + "-" + "\0");
								
								if(stats != null) {
									for(Statistics st : stats) {
										if(st.getPlayer_id() == inn.getBattingCard().get(b-1).getPlayerId() && st.getStats_type_id() == 2) {
											if(st.getBalls_faced()==null|| st.getBalls_faced() == 0 || st.getRuns()==null ||st.getRuns()== 0) {
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$StatGrp$Grp" + row_id + "$txt_StatValue2"
														+ "*GEOM*TEXT SET " + "T20 STRIKE RATE : " + "-" + "\0");
											}else {
												strike_rate = st.getRuns() * 100;
												strike_rate = strike_rate/st.getBalls_faced();
												DecimalFormat df = new DecimalFormat("0.0");
												
												print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$NextToBat$StatGrp$Grp" + row_id + "$txt_StatValue2"
														+ "*GEOM*TEXT SET " + "T20 STRIKE RATE : " + df.format(strike_rate) + "\0");
											}
										}
									}
								}
							}
						}
					}
				}
			}
			
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png Band$Side_1$BandIn_1 2.300 Data$Side_1$DataIn_1 2.000 "
					+ "Logo$Side_1$LogoIn_1 1.500 \0");
			TimeUnit.MILLISECONDS.sleep(2500);	
		}
	}
