				print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$PlayerNameSuper$StatGrp$Grp1$txt_StatHead*GEOM*TEXT SET " 
						+ "WICKET KEEPER" +" - " + Home_or_Away + "\0");
