						 print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Score_Grp$PowerPlayGrp*ACTIVE SET 1 \0");
						 print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*PowerPlay_In START \0");
