			print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$DataAll$CenterData$Stage1$ProjectedScore$Text3*GEOM*TEXT SET " + "@RPO " + proj_score_rate[4] + "\0");
