					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$ProjectedScore$StatGrp$Grp3$txt_StatHead"
							+ "*GEOM*TEXT SET " + "@" + proj_score_rate[4] +" RPO" + "\0");
