	public void populateSplit(PrintWriter print_writer,String viz_scene,int whichInning,int splitValue,int whichside, MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
		
			for(Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side" + whichside + "$Single$img_TeamBadges*TEXTURE*IMAGE SET " 
							+ logo_path + inn.getBatting_team().getTeamName4() + "\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$PlyerName$txt_FirstName"
							+ "*GEOM*TEXT SET " + inn.getBatting_team().getTeamName3() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$PlyerName$txt_lastName"
							+ "*GEOM*TEXT SET " + "" + "\0");
					
					if(inn.getTotalWickets() >=10) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$ScoreGrp$txt_Runs*GEOM*TEXT SET " + 
								inn.getTotalRuns() + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$ScoreGrp$txt_Runs*GEOM*TEXT SET " + 
								inn.getTotalRuns() + "-" + inn.getTotalWickets() + "\0");
					}
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$ScoreGrp$txt_Balls*GEOM*TEXT SET " + 
							((6*inn.getTotalOvers()) + inn.getTotalBalls()) + "\0");
					
					if(splitValue == 30) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + 
								"BALLS PER THIRTY" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp1$txt_StatHead*GEOM*TEXT SET " + 
								"THIRTIES" + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + 
								"BALLS PER FIFTY" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp1$txt_StatHead*GEOM*TEXT SET " + 
								"FIFTIES" + "\0");
					}
					
					for(int split_id=2;split_id<=8;split_id++) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp" + split_id + "*ACTIVE SET 0 \0");
			    	}
					
				    for (int i = 0; i < CricketFunctions.getSplit(whichInning, splitValue,match,match.getEventFile().getEvents()).size(); i++) {
				    	int row_id = i + 1;
				    	for(int split_id=1;split_id<=7;split_id++) {
					    	if(split_id <= CricketFunctions.getSplit(whichInning, splitValue,match,match.getEventFile().getEvents()).size()) {
					    		
					    		print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp" + (row_id + 1) + "*ACTIVE SET 1 \0");
					    		
					    		print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp" + (row_id + 1) + "$txt_StatHead"
					    				+ "*GEOM*TEXT SET " + row_id + "\0");
					    		print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + whichside + "$30_50Splits$StatGrp$Grp" + (row_id + 1) + "$txt_StatValue"
					    				+ "*GEOM*TEXT SET " + CricketFunctions.getSplit(whichInning,splitValue,match,match.getEventFile().getEvents()).get(i) + "\0");					    	}
				    	}
			        }
				}
			}
		}
	}	
