	public void populateTieIdDouble(PrintWriter print_writer,String viz_sence_path,String day,List<Fixture> fix,List<Team>team,MatchAllData match, String selectedbroadcaster) throws InterruptedException 
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			String Date = "",match_name="";
			Calendar cal = Calendar.getInstance();
			
			List<Fixture> fx = new ArrayList<Fixture>();
			
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1*FUNCTION*Omo*vis_con SET 0 \0");
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$txt_Header*GEOM*TEXT SET " +
					match.getSetup().getTournament() + "\0");
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$img_EventLogo"
					+ "*TEXTURE*IMAGE SET " + logo_path + "LCT" + "\0");
			
			if(day.toUpperCase().equalsIgnoreCase("TODAY")) {
				Date =  new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$txt_Footer*GEOM*TEXT SET " +
						"TODAY FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");
			}
			else if(day.toUpperCase().equalsIgnoreCase("TOMORROW")) {
				cal.add(Calendar.DATE, +1);
				Date =  new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$txt_Footer*GEOM*TEXT SET " +
						"TOMORROW - LIVE FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");
			}
			
			fx.clear();
			for(int i = 0; i <= fix.size()-1; i++) {
				if(fix.get(i).getDate().equalsIgnoreCase(Date)) {
					fx.add(fix.get(i));
				}
			}
			
			if(fx.size() == 2) {
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$"
						+ "SelectMatches*FUNCTION*Omo*vis_con SET 2 \0");
				
				for(int j=1;j<=fx.size();j++) {
					if(fx.get(j-1).getMatchnumber() < 10) {
						if(fx.get(j-1).getGmtTime() != null) {
							match_name = "MATCH " + fx.get(j-1).getMatchnumber() + " - AT " + fx.get(j-1).getGmtTime(); 
						}else {
							match_name = "MATCH " + fx.get(j-1).getMatchnumber(); 
						}
					}else {
						if(fx.get(j-1).getGmtTime() != null) {
							match_name = fx.get(j-1).getMatchfilename().toUpperCase() + " - AT " + fx.get(j-1).getGmtTime(); 
						}else {
							match_name = fx.get(j-1).getMatchfilename().toUpperCase(); 
						}
					}
					
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$DoubleMatch$"
							+ "Match" + j + "$txt_MatchNumber*GEOM*TEXT SET " + match_name + "\0");
					
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$DoubleMatch$"
							+ "Match" + j + "$HomeBadgeGroup$img_Badges*TEXTURE*IMAGE SET " + logo_path + team.get(fx.get(j-1).getHometeamid()-1).getTeamName4() + "\0");
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$DoubleMatch$"
							+ "Match" + j + "$AwayBadgeGroup$img_Badges*TEXTURE*IMAGE SET " + logo_path + team.get(fx.get(j-1).getAwayteamid()-1).getTeamName4() + "\0");
				}
			}
			else if(fx.size() == 3) {
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$"
						+ "SelectMatches*FUNCTION*Omo*vis_con SET 3 \0");
				for(int j=1;j<=fx.size();j++) {
					if(fx.get(j-1).getMatchnumber() < 10) {
						if(fx.get(j-1).getGmtTime() != null) {
							match_name = "MATCH " + fx.get(j-1).getMatchnumber() + " - AT " + fx.get(j-1).getGmtTime(); 
						}else {
							match_name = "MATCH " + fx.get(j-1).getMatchnumber(); 
						}
					}else {
						if(fx.get(j-1).getGmtTime() != null) {
							match_name = fx.get(j-1).getMatchfilename().toUpperCase() + " - AT " + fx.get(j-1).getGmtTime(); 
						}else {
							match_name = fx.get(j-1).getMatchfilename().toUpperCase(); 
						}
					}
					
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$TripleMatch$"
							+ "Match" + j + "$txt_MatchNumber*GEOM*TEXT SET " + match_name + "\0");
					
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$TripleMatch$"
							+ "Match" + j + "$HomeBadgeGroup$img_Badges*TEXTURE*IMAGE SET " + logo_path + team.get(fx.get(j-1).getHometeamid()-1).getTeamName4() + "\0");
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$TripleMatch$"
							+ "Match" + j + "$AwayBadgeGroup$img_Badges*TEXTURE*IMAGE SET " + logo_path + team.get(fx.get(j-1).getAwayteamid()-1).getTeamName4() + "\0");
					
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$TripleMatch$"
							+ "Match" + j + "$$HomeBadgeGroup$txt_TeamName*GEOM*TEXT SET " + team.get(fx.get(j-1).getHometeamid()-1).getTeamName3() + "\0");
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All$FF$AllActive$OutAnim$Side1$GameIntro$GameIntroOut$GameIntroAll$SelectMatches$TripleMatch$"
							+ "Match" + j + "$$AwayBadgeGroup$txt_TeamName*GEOM*TEXT SET " + team.get(fx.get(j-1).getAwayteamid()-1).getTeamName3() + "\0");
					
				}
			}
			
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_sence_path + " C:/Temp/Preview.png Fullframes 3.020 Fullframes$Essentials$In 3.020 "
					+ "Fullframes$Side1$GameIntro$In 3.020 \0");
		}
		
	}
