	public void populateMiniBattingcard(PrintWriter print_writer, String viz_scene, int whichInning, MatchAllData match, String broadcaster) throws InterruptedException {
		
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: mini batting card inning is null";
		} else {

			int row_id = 0, omo_num = 0,batting_size=0;
			String cont_name= "";
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$LogoMotion*ACTIVE SET 0 \0");
			
			for(Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$LogoMotion$img_TeamBadges*TEXTURE*IMAGE SET " + logo_path +
							inn.getBatting_team().getTeamName4().toUpperCase() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$SubHeaderGrp$SubHeaderText$txt_TeamName*GEOM*TEXT SET " +
							inn.getBatting_team().getTeamName3() + "\0");
					
					Collections.sort(inn.getBattingCard());
					for (BattingCard bc : inn.getBattingCard()) {
						
						row_id = row_id + 1;
						
						switch (bc.getStatus().toUpperCase()) {
							case CricketUtil.OUT:
								omo_num = 0;
								cont_name = "$Dehighlight";
								batting_size = batting_size + 1;
								print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBatter"
										+ "*FUNCTION*Omo*vis_con SET " + batting_size + " \0");
								break;
							case CricketUtil.NOT_OUT:
								omo_num = 1;
								cont_name = "$Highlight";
								batting_size = batting_size + 1;
								print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBatter"
										+ "*FUNCTION*Omo*vis_con SET " + batting_size + " \0");
								break;
							}
						
							print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBatter$Row" + row_id + 
								"$RowAnim$SelectNotOut*FUNCTION*Omo*vis_con SET " + String.valueOf(omo_num) + " \0");
							print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBatter$Row" + row_id + "$RowAnim$SelectNotOut" + cont_name + "$LeftText"
									+ "$txt_BatterName*GEOM*TEXT SET " + bc.getPlayer().getTicker_name() + "\0");
							
							print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBatter$Row" + row_id + "$RowAnim$SelectNotOut" + cont_name + "$LeftText"
									+ "$ScorteGrp$txt_BatterBalls*GEOM*TEXT SET " + String.valueOf(bc.getBalls()) + "\0");
							
							if(bc.getStatus().toUpperCase().equalsIgnoreCase(CricketUtil.OUT)) {
								print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBatter$Row" + row_id + "$RowAnim$SelectNotOut" + cont_name + "$LeftText"
										+ "$ScorteGrp$txt_BatterScore*GEOM*TEXT SET " + bc.getRuns() + "\0");
							}else {
								print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBatter$Row" + row_id + "$RowAnim$SelectNotOut" + cont_name + "$LeftText"
										+ "$ScorteGrp$txt_BatterScore*GEOM*TEXT SET " + bc.getRuns() + "*" + "\0");
							}
			
					}
				}
			}
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 4.000 \0");
		TimeUnit.MILLISECONDS.sleep(2500);
	}
	public void populateMiniBowlingcard(PrintWriter print_writer, String viz_scene, int whichInning, MatchAllData match, String broadcaster) throws InterruptedException {
		
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Bowlingcard's inning is null";
		} else {
			
			int row_id = 0, omo_num = 0,i=0;
			String cont_name= "";
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$LogoMotion*ACTIVE SET 0 \0");
			
			for(Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$LogoMotion$txt_Teambadges*TEXTURE*IMAGE SET " + logo_path +
							inn.getBowling_team().getTeamName4().toUpperCase() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$TopPart$SubHeaderGrp$SubHeaderText$txt_TeamName*GEOM*TEXT SET " +
							inn.getBowling_team().getTeamName3() + "\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SubHeadGrp$txt_OversHead"
							+ "*GEOM*TEXT SET " + "B" + "\0");
					
					for (BowlingCard boc : inn.getBowlingCard()) {
						if(boc.getRuns() > 0 || ((boc.getOvers()*6)+boc.getBalls()) > 0) {
							i=i+1;
							print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber"
									+ "*FUNCTION*Omo*vis_con SET " + i + " \0");
						}
						switch (boc.getStatus().toUpperCase()) {
						case (CricketUtil.OTHER + CricketUtil.BOWLER):
							omo_num = 0;
							cont_name = "$Dehighlight";
							break;
						case (CricketUtil.LAST + CricketUtil.BOWLER):
							omo_num = 0;
							cont_name = "$Dehighlight";
							break;
						case (CricketUtil.CURRENT + CricketUtil.BOWLER):
							omo_num = 1;
							cont_name = "$Highlight";
							break;
						}
						
						row_id = row_id + 1;
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight*FUNCTION*Omo*vis_con SET " + String.valueOf(omo_num) + " \0");
						
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + 
								"$txt_BowlerName*GEOM*TEXT SET " + boc.getPlayer().getTicker_name() + "\0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + "$txt_BowlerOvers"
								+ "*GEOM*TEXT SET " + ((boc.getOvers()*6)+boc.getBalls()) + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + "$txt_BowlerMaiden"
								+ "*GEOM*TEXT SET " + boc.getDots() + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + "$txt_BowlerRuns"
								+ "*GEOM*TEXT SET " + boc.getRuns() + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$YPos$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + "$txt_BowlerWickets"
								+ "*GEOM*TEXT SET " + boc.getWickets() + "\0");
					}
				}
			}
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 4.000 \0");
		TimeUnit.MILLISECONDS.sleep(2500);	
	}
	public void populateThisSeries(PrintWriter print_writer, String viz_scene,int Playerid,String TypeofProfile,List<Tournament> this_series,MatchAllData match, String broadcaster) throws InterruptedException {
		
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			
			double strike_rate = 0 , economy_rate=0;
			int k=0;
		
			List<BestStats> top_batsman_beststats = new ArrayList<BestStats>();
			List<BestStats> top_bowler_beststats = new ArrayList<BestStats>();
			for(Tournament tourn : this_series) {
				for(BestStats bs : tourn.getBatsman_best_Stats()) {
					top_batsman_beststats.add(bs);
				}
				for(BestStats bfig : tourn.getBowler_best_Stats()) {
					top_bowler_beststats.add(bfig);
				}
			}
			
			Collections.sort(top_batsman_beststats, new CricketFunctions.PlayerBestStatsComparator());
			Collections.sort(top_bowler_beststats, new CricketFunctions.PlayerBestStatsComparator());
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side" + which_side + "*FUNCTION*Omo*vis_con SET 9 \0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side" + which_side + "*FUNCTION*Omo*vis_con SET 0 \0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$BandGrp$Side" + which_side + "*FUNCTION*Omo*vis_con SET 3 \0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$MiddleDataGrp$txt_FielderName*GEOM*TEXT SET " + "THIS SERIES" +" \0");

			for(int i = 0; i <= this_series.size() - 1 ; i++) {
				if(this_series.get(i).getPlayerId() == Playerid) {
					System.out.println("Runs "+this_series.get(i).getRuns() );
					if(this_series.get(i).getPlayer().getTeamId() == match.getSetup().getHomeTeamId()) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side1$Single$img_TeamBadges*TEXTURE*IMAGE SET " 
								+ logo_path + match.getSetup().getHomeTeam().getTeamName4() + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Logos_GRP$Side1$Single$img_TeamBadges*TEXTURE*IMAGE SET " 
								+ logo_path + match.getSetup().getAwayTeam().getTeamName4() + "\0");
					}
					
					if(this_series.get(i).getPlayer().getSurname() == null) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$PlyerName$txt_FirstName*GEOM*TEXT SET " + this_series.get(i).getPlayer().getFirstname() + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$PlyerName$txt_lastName*GEOM*TEXT SET " + "" + " \0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$PlyerName$txt_FirstName*GEOM*TEXT SET " + this_series.get(i).getPlayer().getFirstname() + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$PlyerName$txt_lastName*GEOM*TEXT SET " + this_series.get(i).getPlayer().getSurname() + " \0");
					}
					
					
					
					switch(TypeofProfile.toUpperCase()) {
					case CricketUtil.BATSMAN:
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp1$txt_StatHead*GEOM*TEXT SET " + "MATCHES" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp2$txt_StatHead*GEOM*TEXT SET " + "RUNS" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatHead*GEOM*TEXT SET " + "BEST" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatHead*GEOM*TEXT SET " + "STRIKE RATE" + " \0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp1$txt_StatValue*GEOM*TEXT SET " + this_series.get(i).getMatches() + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp2$txt_StatValue*GEOM*TEXT SET " + this_series.get(i).getRuns() + " \0");
						
						
						
						if(this_series.get(i).getBallsFaced() == 0 || this_series.get(i).getRuns()== 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatValue*GEOM*TEXT SET "  + "-" + " \0");
							
						}else {
							strike_rate = this_series.get(i).getRuns() * 100;
							strike_rate = strike_rate/this_series.get(i).getBallsFaced();
							DecimalFormat df = new DecimalFormat("0.0");
							print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatValue*GEOM*TEXT SET "  + df.format(strike_rate) + " \0");
						}
						 
						for(int j=0;j<= top_batsman_beststats.size()-1;j++) {
							if(top_batsman_beststats.get(j).getPlayerId() == Playerid) {
								if(k == 0) {
									k += 1;
									if(top_batsman_beststats.get(j).getBestEquation() % 2 == 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET "  + top_batsman_beststats.get(j).getBestEquation()/2 + " \0");
									
									}else {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET "  + (top_batsman_beststats.get(j).getBestEquation()-1) / 2 + "*" + " \0");
									}
									break;
								}
							}else {
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET " + "-" + " \0");
							}
						}
						break;
					case CricketUtil.BOWLER:
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp1$txt_StatHead*GEOM*TEXT SET " + "MATCHES" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp2$txt_StatHead*GEOM*TEXT SET " + "WICKETS" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatHead*GEOM*TEXT SET " + "BEST" + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatHead*GEOM*TEXT SET " + "ECONOMY" + " \0");
						
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp1$txt_StatValue*GEOM*TEXT SET " + this_series.get(i).getMatches() + " \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp2$txt_StatValue*GEOM*TEXT SET " + this_series.get(i).getWickets() + " \0");
						
						
						if(this_series.get(i).getBallsBowled() == 0 || this_series.get(i).getRunsConceded() == 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatValue*GEOM*TEXT SET "  + "-" + " \0");
						}else {
							economy_rate = (this_series.get(i).getRunsConceded()*1.00) /this_series.get(i).getBallsBowled();
							economy_rate = economy_rate * 6;
							DecimalFormat df = new DecimalFormat("0.00");
							print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp3$txt_StatValue*GEOM*TEXT SET " + df.format(economy_rate) + " \0");
						}
						
						for(int j=0;j<= top_bowler_beststats.size()-1;j++) {
							if(top_bowler_beststats.get(j).getPlayerId() == Playerid) {
								if(k == 0) {
									k += 1;
									if(top_bowler_beststats.get(j).getBestEquation() % 1000 > 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET " + ((top_bowler_beststats.get(j).getBestEquation() / 1000) +1) + "-" + (1000 - (top_bowler_beststats.get(j).getBestEquation() % 1000)) + " \0");
									}
									else if(top_bowler_beststats.get(j).getBestEquation() % 1000 < 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET " + (top_bowler_beststats.get(j).getBestEquation() / 1000) + "-" + Math.abs(top_bowler_beststats.get(j).getBestEquation()) + " \0");
									}
									break;
								}
							}else if(top_bowler_beststats.get(j).getPlayerId() != Playerid) {
								print_writer.println("-1 RENDERER*TREE*$Main$All$DataGrp$Side1$PlayerCareer_4Stats$StatGrp$Grp4$txt_StatValue*GEOM*TEXT SET " + "-" + " \0");
							}
						}
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png Band$Side_1$BandIn_1 2.300 Data$Side_1$DataIn_1 2.000 "
					+ "DIRECTOR*Logo$Side_1$LogoIn_1 1.500 \0");
			TimeUnit.MILLISECONDS.sleep(500);
		}
	}
	
